  1#RS:/**
  2#NN: * Document Registry — scans a docs folder, parses frontmatter, maintains index.
  3#SZ: *
  4#PJ: * Processing pipeline:
  5#YK: * 1. stat(filePath) → size check, mtime check, cache hit
  6#XY: * 2. readFile(filePath) → parse frontmatter or generate keywords
  7#YW: */
  8#TK:import type { Dirent } from "node:fs";
  9#KB:import { readdir, readFile, stat } from "node:fs/promises";
 10#RX:import { basename, extname, join, relative, resolve } from "node:path";
 11#XJ:import type { CacheEntry, DocEntry, DocInjectorConfig, KeywordCache } from "./types";
 12#RZ:import type { Notifier } from "./notifier";
 13#TV:import { createGlobFilter } from "./globber";
 14#PJ:import { generateKeywords } from "./keyword-gen";
 15#RJ:
 16#MB:/**
 17#ZK: * Shared parser for frontmatter block content (title + keywords).
 18#WS: * Extracts title and keywords from YAML-like content between delimiters.
 19#QB: */
 20#XV:function parseFrontmatterBlock(block: string): { title: string; keywords: string[] } | null {
 21#YR:  // Extract title
 22#YZ:  const titleMatch = block.match(/^title:\s*["']?([^"'\n]+)["']?$/m);
 23#KT:  const title = titleMatch ? titleMatch[1].trim() : "";
 24#KW:
 25#MK:  // Extract keywords — supports both flow array [a, b] and block array
 26#VJ:  const keywords: string[] = [];
 27#JJ:
 28#VX:  // Try flow array: keywords: [a, b, c]
 29#WS:  const flowMatch = block.match(/keywords:\s*\[([^\]]*)\]/);
 30#HK:  if (flowMatch) {
 31#YW:    keywords.push(
 32#WT:      ...flowMatch[1]
 33#KY:        .split(",")
 34#WW:        .map((k) => k.trim().replace(/^["']|["']$/g, ""))
 35#BK:        .filter(Boolean),
 36#VM:    );
 37#SJ:  } else {
 38#SQ:    // Try block array: keywords:\n  - a\n  - b
 39#TZ:    const blockMatches = block.matchAll(/keywords:\s*\n((?:\s*-\s*.+\n?)+)/g);
 40#KH:    for (const bm of blockMatches) {
 41#YK:      const items = bm[1].matchAll(/^\s*-\s*["']?([^"'\n]+)["']?$/gm);
 42#MQ:      for (const im of items) {
 43#JQ:        const k = im[1].trim();
 44#ZV:        if (k) keywords.push(k);
 45#KB:      }
 46#VP:    }
 47#WW:  }
 48#BY:
 49#KP:  if (keywords.length === 0) {
 50#MW:    return null;
 51#ZV:  }
 52#NM:
 53#ZP:  return { title: title || "Untitled", keywords };
 54#QH:}
 55#TW:
 56#WZ:/**
 57#MY: * Parse YAML-style frontmatter: `--- ... ---`
 58#RX: */
 59#JT:function parseYamlFrontmatter(
 60#RM:  content: string,
 61#QB:): { title: string; keywords: string[]; body: string } | null {
 62#RS:  if (!content.startsWith("---")) return null;
 63#JN:
 64#YM:  const secondDash = content.indexOf("---", 3);
 65#VK:  if (secondDash === -1) return null;
 66#JQ:
 67#KN:  const block = content.slice(3, secondDash).trim();
 68#ZS:  const body = content.slice(secondDash + 3).trim();
 69#KB:
 70#KJ:  const parsed = parseFrontmatterBlock(block);
 71#BH:  if (!parsed) return null;
 72#SV:
 73#NT:  return { ...parsed, body };
 74#XK:}
 75#SZ:
 76#BM:/**
 77#PT: * Parse C-style block comment frontmatter: `/*--- ... ---*​/`
 78#KK: */
 79#HX:function parseCStyleFrontmatter(
 80#RM:  content: string,
 81#QB:): { title: string; keywords: string[]; body: string } | null {
 82#KP:  if (!content.startsWith("/*---")) return null;
 83#YX:
 84#NT:  const end = content.indexOf("---*/", 5);
 85#QT:  if (end === -1) return null;
 86#KR:
 87#RM:  let block = content.slice(5, end).trim();
 88#XQ:  const body = content.slice(end + 5).trim();
 89#WY:
 90#RR:  // Strip optional "* " or " * " prefix from each line (common in block comments)
 91#NJ:  block = block
 92#KK:    .split("\n")
 93#ZV:    .map((line) => line.replace(/^\s*\*\s?/, ""))
 94#YM:    .join("\n");
 95#MS:
 96#KJ:  const parsed = parseFrontmatterBlock(block);
 97#BH:  if (!parsed) return null;
 98#BP:
 99#NT:  return { ...parsed, body };
100#MN:}
101#ZS:
102#TH:/**
103#ZW: * Parse HTML comment frontmatter: `<!-- ... -->`
104#SN: */
105#NK:function parseHTMLFrontmatter(
106#RM:  content: string,
107#QB:): { title: string; keywords: string[]; body: string } | null {
108#KX:  if (!content.startsWith("<!--")) return null;
109#BP:
110#BN:  const end = content.indexOf("-->", 4);
111#QT:  if (end === -1) return null;
112#QJ:
113#YH:  const block = content.slice(4, end).trim();
114#YX:  const body = content.slice(end + 3).trim();
115#PV:
116#KJ:  const parsed = parseFrontmatterBlock(block);
117#BH:  if (!parsed) return null;
118#RM:
119#NT:  return { ...parsed, body };
120#WP:}
121#QY:
122#PK:/**
123#PK: * Parse slash-slash comment frontmatter: `//--- ...` (blank line terminates).
124#HV: */
125#XN:function parseSlashSlashFrontmatter(
126#RM:  content: string,
127#QB:): { title: string; keywords: string[]; body: string } | null {
128#KR:  if (!content.startsWith("//---")) return null;
129#HP:
130#MR:  // Ensure //--- is followed by a newline (its own line)
131#TY:  const afterOpener = content.indexOf("\n", 5);
132#QY:  if (afterOpener === -1) return null;
133#BM:
134#HN:  const rest = content.slice(afterOpener + 1);
135#QX:
136#TM:  // Find blank line terminator
137#TJ:  const blankLineIdx = rest.indexOf("\n\n");
138#KK:
139#XQ:  let block: string;
140#PP:  let body: string;
141#WX:
142#BK:  if (blankLineIdx === -1) {
143#BY:    // No blank line — remaining content is frontmatter block, body is empty
144#MX:    block = rest;
145#WT:    body = "";
146#SJ:  } else {
147#BX:    block = rest.slice(0, blankLineIdx);
148#KY:    body = rest.slice(blankLineIdx + 2).trim();
149#QN:  }
150#PY:
151#XY:  // Strip optional "//" prefix from each line
152#NJ:  block = block
153#KK:    .split("\n")
154#JT:    .map((line) => line.replace(/^\/\/\s?/, ""))
155#YK:    .join("\n")
156#WH:    .trim();
157#HJ:
158#KJ:  const parsed = parseFrontmatterBlock(block);
159#BH:  if (!parsed) return null;
160#ZB:
161#NT:  return { ...parsed, body };
162#WJ:}
163#VQ:
164#MH:/**
165#YV: * Parse frontmatter from content, trying each supported style in order.
166#QN: * Returns { title, keywords, body } or null if no valid frontmatter found.
167#PM: *
168#BB: * Styles tried: YAML (---), C-style block (/*---), HTML comment (<!--),
169#YB: * slash-slash comment (//---, blank-line terminated).
170#ZY: */
171#RZ:export function parseFrontmatter(
172#RM:  content: string,
173#QB:): { title: string; keywords: string[]; body: string } | null {
174#MP:  return (
175#TT:    parseYamlFrontmatter(content)
176#ZQ:    ?? parseCStyleFrontmatter(content)
177#PJ:    ?? parseHTMLFrontmatter(content)
178#BB:    ?? parseSlashSlashFrontmatter(content)
179#BK:  );
180#PM:}
