189#RS:
190#YX:/**
191#VS: * Simple promise pool that runs async tasks with a concurrency limit.
192#TS: * Used for parallel file I/O during rebuild.
193#NK: */
194#JV:class PromisePool {
195#ZX:  private running = 0;
196#HV:  private waitResolve: (() => void) | null = null;
197#MH:
198#RP:  constructor(private concurrency: number) {}
199#BN:
200#YQ:  /**
201#SV:   * Run all tasks with at most `concurrency` in flight at once.
202#YB:   * Returns results in the same order as the input tasks.
203#VS:   */
204#VJ:  async all<T>(tasks: Array<() => Promise<T>>): Promise<T[]> {
205#NW:    const results: T[] = new Array(tasks.length);
206#ZY:    let nextIndex = 0;
207#NH:
208#BY:    const worker = async (): Promise<void> => {
209#BH:      while (nextIndex < tasks.length) {
210#XK:        const idx = nextIndex++;
211#WR:        results[idx] = await tasks[idx]();
212#TR:      }
213#WV:    };
214#KZ:
215#VP:    const workerCount = Math.min(this.concurrency, tasks.length);
216#SM:    const workers = Array.from({ length: workerCount }, () => worker());
217#TY:    await Promise.all(workers);
218#QV:
219#MJ:    return results;
220#NM:  }
221#ZN:}
