225#QV:/**
226#XV: * Document Registry class. Scans a docs folder and maintains an index of DocEntry.
227#PR: */
228#QZ:export class DocRegistry {
229#QW:    private entries: DocEntry[] = [];
230#JT:    private docsPath: string;
231#ZJ:    private config: DocInjectorConfig;
232#HZ:    private cache: KeywordCache | null = null;
233#TW:    private dirtyCache: KeywordCache = { version: 1, files: {} };
234#ZQ:    private notifier: Notifier;
235#WJ:
236#QM:    private constructor(
237#SN:        docsPath: string,
238#HX:        config: DocInjectorConfig,
239#KV:        cache: KeywordCache | undefined,
240#ZS:        notifier: Notifier,
241#RM:    ) {
242#JS:        this.docsPath = docsPath;
243#VS:        this.config = config;
244#VJ:        this.cache = cache ?? null;
245#NM:        this.notifier = notifier;
246#YN:    }
247#KJ:
248#QP:    /** Create a registry by scanning the docs folder. */
249#TW:    static async create(
250#SN:        docsPath: string,
251#HX:        config: DocInjectorConfig,
252#KV:        cache: KeywordCache | undefined,
253#ZS:        notifier: Notifier,
254#ZW:    ): Promise<DocRegistry> {
255#XH:        const registry = new DocRegistry(docsPath, config, cache, notifier);
256#HK:        await registry.rebuild();
257#XW:        return registry;
258#PZ:    }
259#WQ:
260#XK:  /** Re-scan the docs folder and rebuild the index. */
261#VK:  async rebuild(): Promise<void> {
262#PN:    const resolved = resolve(this.docsPath);
263#TS:    const preserved = new Map<string, boolean>();
264#RJ:    for (const e of this.entries) {
265#XW:      preserved.set(e.filePath, e.injected);
266#PN:    }
267#QQ:
268#TM:    // Start with a fresh dirty cache — only files that changed get added
269#JX:    this.dirtyCache = { version: 1, files: {} };
270#ZB:
271#VN:    try {
272#BN:      const scanResults = this.config.recursive
273#TW:        ? await this.scanRecursive(resolved)
274#BY:        : await this.scanFlat(resolved);
275#MV:
276#JW:      // Process files concurrently with PromisePool
277#WZ:      const pool = new PromisePool(this.config.maxConcurrent);
278#NB:
279#WM:      const tasks = scanResults.map((sr) => async (): Promise<DocEntry | null> => {
280#ZZ:        return this.processFile(sr, preserved);
281#QJ:      });
282#QT:
283#HS:      const results = await pool.all(tasks);
284#TJ:      this.entries = results.filter((e): e is DocEntry => e !== null);
285#XP:    } catch {
286#YB:      this.notifier.warn(`[doc-injector] Docs folder not found: ${resolved}`);
287#XS:      this.entries = [];
288#WQ:    }
289#NN:  }
290#YM:
291#SY:  /**
292#PR:   * Process a single file through the full pipeline.
293#WW:   * Returns a DocEntry or null if the file should be skipped.
294#NH:   */
295#ZS:  private async processFile(
296#TH:    { filePath, relativePath, fileName }: ScanResult,
297#JZ:    preserved: Map<string, boolean>,
298#WR:  ): Promise<DocEntry | null> {
299#VN:    try {
300#VB:      // ═══ METADATA + CACHE ═══
301#RM:
302#KT:      // Step 1: Stat the file for size and mtime
303#NT:      const fileStat = await stat(filePath);
304#VX:
305#YN:      // Step 2: Skip files exceeding maxFileSize
306#VT:      if (fileStat.size > this.config.maxFileSize) {
307#PK:        this.notifier.warn(
308#YH:          `[doc-injector] Skipping ${relativePath}: size ${fileStat.size} > max ${this.config.maxFileSize}`,
309#HQ:        );
310#QM:        return null;
311#HV:      }
312#NW:
313#ZQ:      const cachedEntry = this.cache?.files[relativePath];
314#RN:
315#VY:      // Step 6: Cache hit — mtime matches, use cached keywords
316#VH:      if (cachedEntry && cachedEntry.mtimeMs === fileStat.mtimeMs) {
317#YP:        // Still read the file for content and title (needed for injection),
318#TB:        // but skip keyword generation entirely
319#MB:        const raw = await readFile(filePath, "utf-8");
320#BB:        const title = extractTitle(raw, fileName);
321#JW:
322#JJ:        return {
323#XJ:          filePath,
324#QW:          fileName,
325#VR:          relativePath,
326#XH:          title,
327#HT:          keywords: cachedEntry.keywords,
328#WN:          content: raw,
329#ZX:          injected: preserved.get(filePath) ?? false,
330#JN:          keywordSource: "cache",
331#QZ:        };
332#NP:      }
333#QV:
334#TB:      // ═══ FULL READ + PARSE (cache miss) ═══
335#NZ:
336#RB:      // Step 7: Read file content
337#JP:      const raw = await readFile(filePath, "utf-8");
338#XN:
339#PX:      // Step 8: Try frontmatter parsing
340#QN:      const parsed = parseFrontmatter(raw);
341#PS:
342#WH:      let title: string;
343#XM:      let keywords: string[];
344#XV:      let keywordSource: DocEntry["keywordSource"];
345#QR:
346#QQ:      if (parsed) {
347#WX:        // Step 9: Frontmatter found — use its title and keywords
348#ZS:        title = parsed.title;
349#NS:        keywords = parsed.keywords;
350#RZ:        keywordSource = "frontmatter";
351#QR:      } else if (this.config.autoKeywords) {
352#HP:        // Step 10: No frontmatter, generate keywords heuristically
353#ZR:        title = extractTitle(raw, fileName);
354#BV:        keywords = generateKeywords(fileName, raw);
355#MW:        keywordSource = "heuristic";
356#PM:      } else {
357#HX:        // Step 11: No frontmatter and autoKeywords disabled — skip
358#PK:        this.notifier.warn(
359#YX:          `[doc-injector] Skipping ${relativePath}: no valid frontmatter with keywords`,
360#TZ:        );
361#QM:        return null;
362#TS:      }
363#SV:
364#MJ:      // ═══ CACHE UPDATE ═══
365#RJ:
366#TB:      // Step 12: Mark as dirty (mtime changed or keywords generated)
367#SR:      this.dirtyCache.files[relativePath] = {
368#KW:        mtimeMs: fileStat.mtimeMs,
369#BR:        keywords,
370#SR:      };
371#MZ:
372#MP:      return {
373#VQ:        filePath,
374#SH:        fileName,
375#RV:        relativePath,
376#TM:        title,
377#BR:        keywords,
378#RR:        content: raw,
379#XV:        injected: preserved.get(filePath) ?? false,
380#HX:        keywordSource,
381#NX:      };
382#ZY:    } catch (err) {
383#KK:      // Only warn for unexpected errors, not ENOENT (file deleted/moved after scan)
384#VP:      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
385#KQ:        this.notifier.warn(`[doc-injector] Error reading ${relativePath}: ${err instanceof Error ? err.message : String(err)}`);
386#YW:      }
387#BX:      return null;
388#YR:    }
389#HR:  }
