391#NX:  /** Scan files (non-recursive) filtered by glob. */
392#VK:  private async scanFlat(dir: string): Promise<ScanResult[]> {
393#QM:    const filter = createGlobFilter(this.config.include, this.config.exclude);
394#YS:    const entries = await readdir(dir);
395#SY:    return entries
396#YP:      .filter((f) => filter.match(f))
397#NR:      .map((f) => ({
398#HN:        filePath: join(dir, f),
399#QB:        relativePath: f,
400#MM:        fileName: f,
401#WR:      }));
402#KW:  }
403#HT:
404#TY:  /** Scan files recursively filtered by glob. */
405#ZP:  private async scanRecursive(dir: string): Promise<ScanResult[]> {
406#QM:    const filter = createGlobFilter(this.config.include, this.config.exclude);
407#BW:    const results: ScanResult[] = [];
408#YT:    const dirents = await readdir(dir, { recursive: true, withFileTypes: true }) as Dirent[];
409#XK:
410#HN:    for (const dirent of dirents) {
411#YQ:      if (!dirent.isFile()) continue;
412#XY:
413#RN:      const fileName = basename(dirent.name);
414#QM:
415#KQ:      // Resolve relative path cross-runtime
416#WR:      let relPath: string;
417#SY:      if (dirent.name === fileName) {
418#ZS:        const parentPath = (dirent as Dirent & { parentPath?: string; path?: string }).parentPath
419#TP:          ?? (dirent as Dirent & { path?: string }).path
420#NT:          ?? "";
421#RT:        relPath = parentPath
422#RT:          ? relative(dir, join(parentPath, dirent.name))
423#XH:          : dirent.name;
424#PM:      } else {
425#QV:        relPath = dirent.name;
426#JB:      }
427#XK:
428#WW:      // Apply glob filter
429#XJ:      if (!filter.match(relPath)) continue;
430#WZ:
431#JS:      results.push({
432#KR:        filePath: join(dir, relPath),
433#QR:        relativePath: relPath,
434#SH:        fileName,
435#RJ:      });
436#JM:    }
437#YY:
438#MJ:    return results;
439#JX:  }
